  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (1, 'How the campus works', 'Five minutes on activities, competitions, playlists and your review queue.', '[{"t": "heading", "text": "Explore"}, {"t": "text", "text": "Categories hold **activities** you can do any time. Mark them done to earn house points and keep track of what you have tried."}, {"t": "heading", "text": "Competitions & challenges"}, {"t": "text", "text": "Enter before they close. Staff pick winners, and winners can be shown in the gallery with your permission."}, {"t": "heading", "text": "Schoolwork"}, {"t": "text", "text": "Lessons, playlists, quizzes and homework from your class live under Schoolwork. Anything you get wrong comes back in your review queue until it sticks."}]'::jsonb, 5, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (1, 'Set three goals for this term', 'Ten minutes to decide what you want out of the next few weeks.', '[{"t": "text", "text": "Write three goals: one for a subject, one for something outside lessons, one for how you treat people. Make each one something you could tick off."}, {"t": "key", "q": "What makes a goal useful?", "text": "It is specific enough that you would know when it is done. ''Get better at maths'' is a wish; ''pass the algebra checkpoint by half term'' is a goal."}, {"t": "check", "q": "Which goal is the most useful?", "a": ["Try harder", "Read one book a month", "Be good", "Do well"], "c": 1}]'::jsonb, 10, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (2, 'One-line portrait', 'Draw a face without lifting your pen. Ten minutes, three attempts.', '[{"t": "text", "text": "Pick someone in the room (or a photo). Draw their face in **one continuous line**: the pen never leaves the paper."}, {"t": "list", "items": ["Start at the forehead and work round.", "Don''t look at the page for the first attempt.", "Third attempt: slow down and add an ear."]}, {"t": "key", "q": "What does a continuous line drawing teach?", "text": "Looking. You have to keep your eyes on the subject, so you notice shapes you would otherwise invent."}]'::jsonb, 15, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (2, 'Photograph light, not things', 'Take five photos where light is the subject.', '[{"t": "text", "text": "Walk around for 20 minutes with a phone. Photograph **light itself**: a shadow, a reflection, a beam through a window, a silhouette."}, {"t": "list", "items": ["Turn the flash off.", "Try one photo with the sun behind the subject.", "Crop tightly; leave out anything that is not about the light."]}, {"t": "key", "q": "What is the golden hour?", "text": "The hour after sunrise and before sunset, when sunlight is low, warm and soft, so shadows are long and gentle."}, {"t": "check", "q": "Which makes the softest light?", "a": ["Midday sun", "An overcast sky", "A phone torch", "A bare bulb"], "c": 1}]'::jsonb, 30, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (3, 'Map your food''s journey', 'Find where five things in your kitchen came from and plot them.', '[{"t": "text", "text": "Look at the labels of five foods at home. Find the country of origin and work out roughly how far each one travelled."}, {"t": "key", "q": "What are food miles?", "text": "The distance food travels from where it is grown to where it is eaten. More miles usually means more transport emissions, but a greenhouse tomato grown nearby can use more energy than one shipped from a sunny country."}]'::jsonb, 45, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (3, 'A week of weather', 'Record the weather every day for a week and explain one change.', '[{"t": "text", "text": "Each day note the temperature, wind direction and sky. At the end of the week pick one change (a cold snap, a rainy day) and explain what caused it."}, {"t": "key", "q": "Where does the UK''s weather mostly come from?", "text": "The west. Prevailing south-westerly winds bring mild, wet air from the Atlantic, which is why the west of the country is wetter than the east."}, {"t": "check", "q": "A rapid drop in temperature with heavy rain usually means…", "a": ["A cold front has passed", "High pressure", "Fog", "A heatwave"], "c": 0}]'::jsonb, 20, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (4, 'Rhythm from your name', 'Turn the syllables of your name into a four-bar rhythm you can clap.', '[{"t": "text", "text": "Say your full name and count the syllables. Each syllable becomes a beat. Clap it, then add a second person''s name underneath."}, {"t": "key", "q": "What is a bar?", "text": "A fixed group of beats. In 4/4 time every bar has four beats."}]'::jsonb, 20, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (4, 'Thirty-second monologue', 'Learn and perform a short speech, then change one thing.', '[{"t": "text", "text": "Choose 30 seconds of a speech from any play or film. Learn it. Perform it once as the character, then once as if you were furious, then once as if you were terrified."}, {"t": "key", "q": "What is subtext?", "text": "What a character means but does not say. Changing the emotion changes the subtext even when the words stay the same."}, {"t": "check", "q": "Which is subtext?", "a": ["The words on the page", "What the character really means", "The stage directions", "The costume"], "c": 1}]'::jsonb, 25, '11plus', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (5, 'Two-minute speech: the thing nobody understands', 'Prepare and deliver a 120-second talk explaining something you love.', '[{"t": "text", "text": "Choose a hobby, a game or a topic that people around you don''t get. Explain it in **two minutes** to someone who knows nothing about it."}, {"t": "heading", "text": "Structure"}, {"t": "list", "items": ["Hook: one surprising fact.", "Three things they need to know.", "Why it matters to you."]}, {"t": "key", "q": "What is the single most useful public-speaking habit?", "text": "Pausing. A pause after an important point gives the audience time to catch up and makes you sound confident."}]'::jsonb, 30, '11plus', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (5, 'Six-word stories', 'Write ten stories of exactly six words. Pick your best.', '[{"t": "text", "text": "The famous example is ''For sale: baby shoes, never worn.'' Write ten of your own. Every word has to earn its place."}, {"t": "key", "q": "Why do very short stories work?", "text": "They leave a gap the reader fills in. The story happens in the reader''s head, not on the page."}, {"t": "check", "q": "How many words?", "a": ["Five", "Six", "Seven", "As many as you like"], "c": 1}]'::jsonb, 15, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (6, 'Plan a 10-minute kindness campaign', 'Design a small thing your class could do for someone else this week.', '[{"t": "text", "text": "Pick one group of people: new Year 7s, the canteen staff, a local care home. Plan one thing your class could do for them in ten minutes."}, {"t": "list", "items": ["Who benefits and how do you know they would want it?", "What does it cost (time, money, permission)?", "How will you tell people about it?"]}]'::jsonb, 30, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (6, 'Interview someone older', 'Ask three questions about school in their day and write up what surprised you.', '[{"t": "text", "text": "Find someone at least 30 years older than you. Ask what a school day was like, what they worried about, and what they wish they had known. Write 150 words on what surprised you most."}, {"t": "key", "q": "Why interview rather than search?", "text": "A person gives you the details nobody wrote down: the smell of the dinner hall, the teacher everyone feared. Those are the details that make writing real."}]'::jsonb, 40, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (7, 'Build a paper bridge that holds a mug', 'Engineering challenge with one sheet of A4 and 30 cm of tape.', '[{"t": "text", "text": "You have **one sheet of A4 paper** and **30 cm of sticky tape**. Build a bridge between two books 20 cm apart that holds a full mug of water."}, {"t": "heading", "text": "Think like an engineer"}, {"t": "list", "items": ["Folds make paper stiff: try a concertina or a tube.", "Where does the weight push? Put strength there.", "Test, fail, improve: engineers never get it right first time."]}, {"t": "key", "q": "Why does folding paper make it stronger?", "text": "Folds turn a flat sheet into a shape with depth, so bending has to stretch and squash more material. Depth is what gives beams their strength."}, {"t": "check", "q": "Which shape usually holds the most for its weight?", "a": ["Flat sheet", "Triangles / concertina", "A crumpled ball", "A loose roll"], "c": 1}]'::jsonb, 40, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (7, 'Estimate, then measure', 'Guess five measurements around you, then check. Who gets closest?', '[{"t": "text", "text": "Before measuring, write down your guess for: the height of the door, the length of the corridor, the weight of your bag, the time it takes to walk round the field, the number of tiles on the ceiling. Then measure or count each one."}, {"t": "key", "q": "What is an order-of-magnitude estimate?", "text": "A guess that aims to be right to within a factor of ten. Scientists use it to check whether an answer is even roughly sensible."}, {"t": "check", "q": "A classroom door is roughly…", "a": ["0.2 m tall", "2 m tall", "20 m tall", "200 m tall"], "c": 1}]'::jsonb, 20, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (8, 'Seven-day sleep diary', 'Track bedtime, wake-up and how you felt. Spot the pattern.', '[{"t": "text", "text": "Every morning for a week, note when you went to bed, when you woke and how you felt out of 10."}, {"t": "key", "q": "How much sleep do 11 to 14 year olds need?", "text": "About 9 to 11 hours. Screens before bed push sleep later because the light tells your brain it is still daytime."}]'::jsonb, 10, 'all', true, 5);
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) values (8, 'Two minutes of stillness', 'A breathing exercise you can do at your desk before a test.', '[{"t": "text", "text": "Sit up, feet flat. Breathe in for four counts, hold for four, out for six. Repeat for two minutes. Notice where your attention goes and bring it back to the counting."}, {"t": "key", "q": "Why does a long out-breath calm you?", "text": "It slows the heart slightly and signals to the nervous system that there is no emergency. Athletes and surgeons use the same trick."}, {"t": "check", "q": "Which part of the breath is longest?", "a": ["In", "Hold", "Out", "All the same"], "c": 2}]'::jsonb, 5, 'all', true, 5);
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) values (7, 'competition', 'STEAM Build-Off: the strongest paper bridge', 'Photo and a short explanation of your design. Judged on load held and clarity.', '[{"t": "text", "text": "Build a bridge from one sheet of A4 and 30 cm of tape (see the activity). Enter a photo and a **three-sentence** explanation of why your design works."}, {"t": "key", "q": "Judging", "text": "50% load held, 50% explanation."}]'::jsonb, now(), now() + interval '21 days', 'all');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) values (5, 'challenge', '100-word story: ''The last light''', 'Exactly 100 words. Any genre.', '[{"t": "text", "text": "Write a story of **exactly 100 words** that includes the phrase ''the last light''. Paste it in the entry box."}]'::jsonb, now(), now() + interval '28 days', '11plus');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) values (2, 'competition', 'Photo competition: light', 'One photo, taken by you, where light is the subject.', '[{"t": "text", "text": "Theme: **light**. One photo, a title and one sentence about where you took it. Phone photos are fine."}]'::jsonb, now(), now() + interval '35 days', 'all');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) values (8, 'tournament', 'Inter-form table tennis', 'Sign up here; fixtures go on the calendar once entries close.', '[{"t": "text", "text": "Enter with your name and form. Matches run at lunchtime in the sports hall."}]'::jsonb, now(), now() + interval '14 days', 'all');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) values (7, 'Robotics club', 'Build and program small robots. No experience needed.', 'Tuesday', '12:30', 'Computing room', 16, 'all');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) values (4, 'Drama club', 'Games, improvisation and the summer show.', 'Wednesday', '15:30', 'Drama studio', 25, 'all');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) values (8, 'Running club', 'A gentle 2 km around the field, all paces welcome.', 'Friday', '07:45', 'Front gate', 30, 'all');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) values (5, 'Debate society', 'Argue the big questions.', 'Thursday', '12:30', 'Library', 12, '11plus');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) values (2, 'Art club', 'Open studio: bring a project or start one.', 'Monday', '15:30', 'Art room', 20, 'all');
  insert into public.ed_news (title, body, featured) values ('Welcome to the Compass Ed campus', 'Compass Ed has everything in one place: activities to explore in your own time, competitions and challenges with real prizes, the school calendar, and your class''s lessons and homework.
  insert into public.ed_news (title, body, featured) values ('Clubs are open for sign-up', 'Five clubs are listed under Explore. Places are first come, first served, and you can leave a club at any time from the same page.', false);
  insert into public.ed_event (kind, title, starts, ends, place) values ('event', 'Compass Ed launch assembly', date_trunc('day', now()) + interval '7 days 9 hours', date_trunc('day', now()) + interval '7 days 9 hours 30 minutes', 'Main hall');
